import{L as e,b as t,x as n}from"./vue-Vea_iehr.js";import{oi as r}from"./common-nRmWVNEZ.js";var i=JSON.parse(`{"path":"/os/debian/4odhnhal/","title":"Debian 修改 IP 地址 | Debian","lang":"zh-CN","frontmatter":{"title":"Debian 修改 IP 地址","createTime":"2026/08/26 15:23:54","permalink":"/os/debian/4odhnhal/"},"readingTime":{"minutes":1.69,"words":506},"git":{},"filePathRelative":"os/debian/02.Standard 镜像/001.changing-ip-address-debian.md","headers":[]}`),a={name:`001.changing-ip-address-debian.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h2 id="概述" tabindex="-1"><a class="header-anchor" href="#概述"><span>概述</span></a></h2><p>新安装的 Debian 系统默认一般通过 DHCP 获取 IP 地址，除非在安装过程中指定了静态 IP。本文记录如何在 Debian 中配置静态 IP 地址、网关以及 DNS 服务器。整个过程只需修改两个配置文件即可完成，相比 Red Hat 系修改 <code>/etc/sysconfig/network-scripts/ifcfg-eXX</code> 的方式更为直接。</p><h2 id="一、确认网络接口并备份配置" tabindex="-1"><a class="header-anchor" href="#一、确认网络接口并备份配置"><span>一、确认网络接口并备份配置</span></a></h2><p>查看当前网络接口名称：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a</span></span></code></pre></div><div class="hint-container note"><p class="hint-container-title">笔记</p><p>现代 Debian 默认采用可预测网卡命名（如 <code>ens18</code>、<code>enp1s0</code>），并非固定的 <code>eth0</code>。下文示例沿用 <code>eth0</code> 作为占位，实际操作时请替换为你机器上 <code>ip a</code> 看到的实际名称。</p></div><p>备份原始配置文件，避免改错后无法回退：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/network/interfaces</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/network/interfaces.bak</span></span></code></pre></div><h2 id="二、配置静态-ip-与网关" tabindex="-1"><a class="header-anchor" href="#二、配置静态-ip-与网关"><span>二、配置静态 IP 与网关</span></a></h2><p>编辑 <code>/etc/network/interfaces</code>：</p><div class="language-ini" data-highlighter="shiki" data-ext="ini" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-ini"><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># The loopback network interface</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auto lo</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">iface lo inet loopback</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># The primary network interface</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">allow-hotplug eth0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auto eth0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">iface eth0 inet static   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># static 表示使用固定 IP，dhcp 表示动态获取</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    address 192.168.9.100    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 静态 IP 地址</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    netmask 255.255.255.0    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 子网掩码</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    gateway 192.168.9.254    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 网关</span></span></code></pre></div><div class="hint-container important"><p class="hint-container-title">重要</p><p>编辑该文件需 root 权限，可用 <code>sudo nano /etc/network/interfaces</code> 打开。</p></div><p>使用 <kbd>Ctrl</kbd>+<kbd>O</kbd> 保存，使用 <kbd>Ctrl</kbd>+<kbd>X</kbd> 退出 nano 编辑器。</p><h2 id="三、配置-dns-服务器" tabindex="-1"><a class="header-anchor" href="#三、配置-dns-服务器"><span>三、配置 DNS 服务器</span></a></h2><p>编辑 <code>/etc/resolv.conf</code>：</p><div class="language-ini" data-highlighter="shiki" data-ext="ini" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-ini"><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nameserver 114.114.114.114   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 首选 DNS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nameserver 8.8.8.8           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 备用 DNS</span></span></code></pre></div><div class="hint-container note"><p class="hint-container-title">笔记</p><p>若系统由 systemd-resolved 或 NetworkManager 接管 DNS，直接修改 <code>resolv.conf</code> 可能在重启后被覆盖；此类环境应在对应服务（NetworkManager 连接配置或 <code>/etc/systemd/resolved.conf</code>）中设置 DNS。</p></div><h2 id="四、使配置生效并验证" tabindex="-1"><a class="header-anchor" href="#四、使配置生效并验证"><span>四、使配置生效并验证</span></a></h2><p>重启网络服务使配置生效：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> networking</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span></span></code></pre></div><p>验证新配置是否工作：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ping</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> www.debian.cn</span></span></code></pre></div><div class="hint-container warning"><p class="hint-container-title">警告</p><p>若重启网络后配置未生效：</p><ol><li>检查是否存在书写错误，尤其是全角/半角字符混用；</li><li><code>interfaces</code> 文件中的 <code>auto eth0</code> 很关键，<code>/etc/init.d/networking</code> 依据该字段判断是否启动对应网卡。</li></ol></div><h2 id="参考" tabindex="-1"><a class="header-anchor" href="#参考"><span>参考</span></a></h2><ul><li><a href="https://www.cnblogs.com/Thenext/p/16950850.html" target="_blank" rel="noopener noreferrer">debian 11 修改 ip 地址的方法 - Thenext - 博客园</a></li></ul>`,25)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};